<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function kimpu_blog_category_links() { $categories = get_categories( array( 'hide_empty' => true ) ); if ( ! $categories ) { return; } echo '<nav class="blog-category-nav" aria-label="' . esc_attr__( 'Blog categories', 'kimpu-multipurpose' ) . '"><a href="' . esc_url( get_permalink( get_option( 'page_for_posts' ) ) ?: home_url( '/' ) ) . '">' . esc_html__( 'All articles', 'kimpu-multipurpose' ) . '</a>'; foreach ( $categories as $category ) { echo '<a href="' . esc_url( get_category_link( $category->term_id ) ) . '">' . esc_html( $category->name ) . '</a>'; } echo '</nav>'; }
function kimpu_blog_related_query_args( $post_id, $limit = 3 ) { $post_id = absint( $post_id ); $limit = max( 1, min( 12, absint( $limit ) ) ); $args = array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => $limit, 'post__not_in' => array( $post_id ), 'ignore_sticky_posts' => true, 'no_found_rows' => true ); $categories = wp_get_post_categories( $post_id ); $tags = wp_get_post_tags( $post_id, array( 'fields' => 'ids' ) ); if ( $categories ) { $args['category__in'] = $categories; } elseif ( $tags ) { $args['tag__in'] = $tags; } return $args; }
